<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\RateLimiter;
use App\Models\User;
use App\Services\AccountChallenges;
use Illuminate\Validation\ValidationException;
class SessionController extends Controller {
 public function csrf(Request $r){return response()->json(['csrf_token'=>$r->session()->token()])->header('Cache-Control','no-store');}
 public function login(Request $r,AccountChallenges $challenges){$r->merge(['email'=>strtolower(trim((string)$r->input('email')))]);$validator=\Illuminate\Support\Facades\Validator::make($r->all(),['email'=>'required|email','password'=>'required|string']);if($validator->fails())throw ValidationException::withMessages(['email'=>'Invalid email or password']);$data=$validator->validated();$user=User::where('email',$data['email'])->first();$applicantKey='applicant-login:'.hash('sha256',$data['email'].'|'.$r->ip());if((!$user||$user->member_type==='applicant')&&RateLimiter::tooManyAttempts($applicantKey,5))throw ValidationException::withMessages(['email'=>'Invalid email or password']);if(!Auth::attempt($data)){if(!$user||$user->member_type==='applicant')RateLimiter::hit($applicantKey,300);throw ValidationException::withMessages(['email'=>'Invalid email or password']);}if(!\App\Services\Administration::active($r->user())){Auth::logout();throw ValidationException::withMessages(['email'=>'Invalid email or password']);}if($r->user()->member_type==='applicant'){RateLimiter::clear($applicantKey);if(!config('portal.sms_enabled')){$r->session()->regenerate();$r->session()->put('login_nonce',(string)\Illuminate\Support\Str::uuid());\App\Services\Administration::audit($r->user(),'session.login','user',$r->user()->id);return $this->show($r);}$applicant=$r->user();Auth::logout();$id=$challenges->issue($applicant,'login','sms');$r->session()->put('applicant_login_challenge',$id);return response()->json(['challenge_id'=>$id,'message'=>'Enter the code sent to your mobile number.',...(config('portal.sms_demo')?['demo_code'=>$r->session()->get('applicant_demo_code.'.$id)]:[])])->header('Cache-Control','no-store');}$r->session()->regenerate();$r->session()->put('login_nonce',(string)\Illuminate\Support\Str::uuid());\App\Services\Administration::audit($r->user(),'session.login','user',$r->user()->id);return $this->show($r);}
 public function applicantVerify(Request $r,AccountChallenges $challenges){$d=$r->validate(['challenge_id'=>'required|uuid','code'=>'required|digits:6']);abort_unless($r->session()->get('applicant_login_challenge')===$d['challenge_id'],422,'Invalid verification code');$key='applicant-code:'.hash('sha256',$d['challenge_id'].'|'.$r->ip());abort_if(RateLimiter::tooManyAttempts($key,5),422,'Invalid verification code');$user=null;$ok=$challenges->redeem($d['challenge_id'],'login',$d['code'],function($u)use(&$user){abort_unless($u->member_type==='applicant',422,'Invalid verification code');$user=$u;$u->phone_verified_at??=now();$u->save();});if(!$ok){RateLimiter::hit($key,300);abort(422,'Invalid verification code');}RateLimiter::clear($key);$r->session()->forget(['applicant_login_challenge','applicant_demo_code.'.$d['challenge_id']]);Auth::login($user);$r->session()->regenerate();$r->session()->put('login_nonce',(string)\Illuminate\Support\Str::uuid());\App\Services\Administration::audit($user,'session.login','user',$user->id);return $this->show($r);}
 public function show(Request $r){return response()->json(['user'=>[...$r->user()->only('id','name','email'),'email_verified'=>(bool)$r->user()->email_verified_at,'phone_verified'=>(bool)$r->user()->phone_verified_at,'account_type'=>$r->user()->member_type,'onboarding_complete'=>(bool)$r->user()->onboarding_completed_at,'mfa_required'=>\App\Services\Administration::requiresMfa($r->user()),'mfa_enrolled'=>(bool)$r->user()->mfa_confirmed_at,'mfa_verified'=>$r->session()->get('mfa_user_id')===$r->user()->id,'is_master'=>\App\Services\Administration::master($r->user()),'permissions'=>collect(['reviews.evaluate','reviews.adjudicate','applications.view','people.manage','reviews.manage','templates.manage','reports.view'])->mapWithKeys(fn($p)=>[$p=>(new \App\Services\ProgrammeAccess)->programmes($r->user(),$p)])->all()]])->header('Cache-Control','no-store');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->noContent();}
}

